    if (type === 'PARTY') { const p = partnerOf(actor.companyId, rid(id)); if (!p || p.partner_status !== 'ACTIVE') fail([{ field: 'custodianId', message: 'Choose an active subcontractor' }]); return { type, id: p.id, name: p.name, user: null }; }
