    if (detail) {
      o.approve = a.status === 'SUBMITTED' && !own && can('inv.small_asset.approve'); if (o.approve && a.workflow_instance_id) o.taskId = taskOf(actor, a.workflow_instance_id); o.disposeAmount = a.dispose_amount; o.disposeReason = a.dispose_reason; o.cancelReason = a.cancel_reason;
      if (a.dispose_status === 'SUBMITTED' && a.dispose_workflow_id && can('inv.small_asset.approve') && !same(a.requested_by, actor.user)) o.disposeTaskId = taskOf(actor, a.dispose_workflow_id);
      o.history = db.prepare('SELECT id, action, from_name AS fromName, to_name AS toName, log_date AS date, ack_method AS ackMethod, ack_status AS ackStatus, asset_condition AS condition, reference, cost, note, done_by AS doneBy FROM ast_custody_log WHERE asset_id = ? ORDER BY id DESC').all(a.id);
      o.losses = db.prepare('SELECT id, doc_no, loss_kind, status FROM ast_loss_reports WHERE asset_id = ? AND deleted_at IS NULL ORDER BY id DESC').all(a.id).map((l) => ({ id: l.id, docNo: l.doc_no, kind: l.loss_kind, status: l.status }));
    }
