      db.prepare('UPDATE ast_small_assets SET tag_code = ?, item_id = ?, store_id = ?, org_project_id = ?, serial_no = ?, make = ?, model = ?, purchase_ref = ?, purchase_date = ?, asset_value = ?, asset_condition = ?, calibration_required = ?, calibration_due = ?, inspection_days = ?, custodian_name = CASE WHEN custodian_type = \'STORE\' THEN ? ELSE custodian_name END, updated_by = ?, updated_at = ?, version = version + 1 WHERE id = ?').run(f.tag || a.tag_code, f.it.id, f.st.id, f.st.org_project_id ?? null, 'serialNo' in b ? b.serialNo : a.serial_no, 'make' in b ? b.make : a.make, 'model' in b ? b.model : a.model, 'purchaseRef' in b ? b.purchaseRef : a.purchase_ref, 'purchaseDate' in b ? b.purchaseDate : a.purchase_date, 'value' in b ? Math.round(b.value * 100) : a.asset_value, b.condition ?? a.asset_condition, f.calReq ? 1 : 0, f.cal, b.inspectionDays ?? a.inspection_days, f.st.code, actor.user, nowIso(), a.id); audit(actor, 'ast_small_assets', a.id, 'update', a.company_id); return assets.get(actor, a.id);
