    cancel(actor, id, { reason }) { const a = arow(actor, id, 'inv.small_asset.cancel'); if (!['DRAFT', 'RETURNED', 'SUBMITTED'].includes(a.status)) throw unprocessable('Only an entry not yet approved is cancelled.'); return transaction(db, () => { if (a.status === 'SUBMITTED') workflowOf(db).abandon(actor.companyId, a.workflow_instance_id, actor.user, 'CANCELLED', reason); db.prepare("UPDATE ast_small_assets SET status = 'CANCELLED', cancel_reason = ?, updated_by = ?, updated_at = ?, version = version + 1 WHERE id = ?").run(reason, actor.user, nowIso(), a.id); audit(actor, 'ast_small_assets', a.id, 'cancel', a.company_id, { reason }); return assets.get(actor, a.id); }); },
